#include "memory_collections.hpp"
#include <chrono>
#include <stdexcept>
namespace krmemory { namespace { std::int64_t now(){return std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count();} }
std::string create_collection(mycelia::DynamicAssociativeDatabase& db,std::string name,std::string kind){if(name.empty()||name.size()>256)throw std::invalid_argument("invalid collection name");mycelia::sql::Row row;row["title"]=std::move(name);row["kind"]=std::move(kind);row["timestamp"]=now();return db.store_sql_record("memory_collections",row);}
std::string assign_to_collection(mycelia::DynamicAssociativeDatabase& db,std::string_view memory,std::string_view collection,std::string origin){if(!db.get_sql_record(memory)||!db.get_sql_record(collection))throw std::invalid_argument("unknown memory or collection");mycelia::sql::Row row;row["memory_signature"]=std::string(memory);row["collection_signature"]=std::string(collection);row["relation_type"]=std::string("belongs_to");row["origin"]=std::move(origin);row["timestamp"]=now();return db.store_sql_record("memory_relationships",row);}
bool rename_collection(mycelia::DynamicAssociativeDatabase& db,std::string_view signature,std::string name){if(name.empty()||name.size()>256)throw std::invalid_argument("invalid collection name");auto record=db.get_sql_record(signature);if(!record||record->table!="memory_collections")return false;auto row=record->data;row["title"]=std::move(name);row["updated_timestamp"]=now();return db.update_sql_record(signature,row);}
bool archive_collection(mycelia::DynamicAssociativeDatabase& db,std::string_view signature,bool archived){auto record=db.get_sql_record(signature);if(!record||record->table!="memory_collections")return false;auto row=record->data;row["archived"]=archived;row["updated_timestamp"]=now();return db.update_sql_record(signature,row);}
std::size_t merge_collections(mycelia::DynamicAssociativeDatabase& db,std::string_view source,std::string_view target){if(source==target)throw std::invalid_argument("source and target collection must differ");auto from=db.get_sql_record(source),to=db.get_sql_record(target);if(!from||!to||from->table!="memory_collections"||to->table!="memory_collections")throw std::invalid_argument("unknown collection");std::size_t moved{};for(const auto& relation:collection_members(db,source)){auto row=relation.data;row["collection_signature"]=std::string(target);row["origin"]=std::string("collection_merge");row["updated_timestamp"]=now();if(db.update_sql_record(relation.signature,row))++moved;}archive_collection(db,source,true);return moved;}
bool delete_collection(mycelia::DynamicAssociativeDatabase& db,std::string_view signature){auto record=db.get_sql_record(signature);if(!record||record->table!="memory_collections")return false;for(const auto& relation:collection_members(db,signature))db.delete_sql_record(relation.signature);return db.delete_sql_record(signature);}
std::vector<mycelia::DynamicAssociativeDatabase::ExternalRecord> collections(const mycelia::DynamicAssociativeDatabase& db){return db.query_sql_like("memory_collections");}
std::vector<mycelia::DynamicAssociativeDatabase::ExternalRecord> collection_members(const mycelia::DynamicAssociativeDatabase& db,std::string_view collection){mycelia::sql::Row f;f["collection_signature"]=std::string(collection);return db.query_sql_like("memory_relationships",f);}
}
